#!/usr/bin/env python3
"""Build the Chicken Little Overwatch Plugin's generated files and release zips.

Generated files (do not edit them by hand):
  agents/clo-*.md          from skills/chicken-little-overwatch/references/roles.md and red-team-swarm.md
  agents.json              the same roles as Muse Code custom agents, for `muse --agents "$(cat agents.json)"`

Usage:
  python3 tools/build.py            write the generated files
  python3 tools/build.py --check    exit 1 if a generated file is stale (no writes)
  python3 tools/build.py --dist DIR also write chicken-little-overwatch.zip and chicken-little-overwatch-plugin.zip to DIR

Each agent file carries only `name` and `description`; rule S1 states the read-only limit in words.
In agents.json, each role also gets `disallowedTools` for Muse Code's file-writing tools, so Muse Code
enforces the read-only limit.
"""
import argparse
import json
import re
import sys
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SKILL = ROOT / "skills" / "chicken-little-overwatch"
REFS = SKILL / "references"
HEADER = "<!-- Generated by tools/build.py from {src}. Edit the source, then rebuild. -->\n"
EXCLUDE = {"__pycache__", ".DS_Store", ".pytest_cache"}


def section(text, heading):
    """Return the body of the level-2 section HEADING, without the heading line."""
    match = re.search(rf"^## {re.escape(heading)}\n(.*?)(?=^## |\Z)", text, re.S | re.M)
    if not match:
        sys.exit(f"build: section '## {heading}' not found")
    return match.group(1).strip()


def parse_roles(text):
    roles = []
    for match in re.finditer(r"^## (clo-[a-z-]+)\n(.*?)(?=^## |\Z)", text, re.S | re.M):
        name, body = match.group(1), match.group(2)
        fields = dict(re.findall(r"^- \*\*(ID|Tiers|Tools|Inline|Description):\*\* (.+)$", body, re.M))
        missing = {"ID", "Tiers", "Tools", "Inline", "Description"} - set(fields)
        if missing:
            sys.exit(f"build: role {name} lacks {sorted(missing)}")
        charter = re.sub(r"^- \*\*(?:ID|Tiers|Tools|Inline|Description):\*\* .+\n", "", body, flags=re.M).strip()
        roles.append((name, fields, charter))
    return roles


def yaml_string(value):
    return json.dumps(value, ensure_ascii=False)


def agent_files():
    roles_text = (REFS / "roles.md").read_text(encoding="utf-8")
    swarm = (REFS / "red-team-swarm.md").read_text(encoding="utf-8")
    shared = section(roles_text, "Shared rules")
    extras = {
        "none": [],
        "lenses": [("Future-risk lenses", section(swarm, "Future-risk lenses"))],
        "defender-rules": [("Defender rules", section(swarm, "Defender rules"))],
    }
    files = {}
    for name, fields, charter in parse_roles(roles_text):
        if fields["Inline"] not in extras:
            sys.exit(f"build: role {name} has unknown Inline value {fields['Inline']}")
        parts = [
            "---",
            f"name: {name}",
            f"description: {yaml_string(fields['Description'])}",
            "---",
            "",
            HEADER.format(src="skills/chicken-little-overwatch/references/roles.md and red-team-swarm.md").rstrip(),
            "",
            f"# {fields['ID']} {name}",
            "",
            f"Tiers: {fields['Tiers']}.",
            "",
            charter,
            "",
            "## Shared rules",
            "",
            shared,
            "",
            "## Finding format",
            "",
            section(swarm, "Finding format"),
            "",
            "## Severity scale",
            "",
            section(swarm, "Severity scale"),
        ]
        for title, body in extras[fields["Inline"]]:
            parts += ["", f"## {title}", "", body]
        files[ROOT / "agents" / f"{name}.md"] = "\n".join(parts) + "\n"
    return files


READ_ONLY_TOOLS_REMOVED = ["write_file", "edit_file"]


def muse_agents(agent_texts):
    """agents.json for Muse Code: each role's description, its whole brief as the prompt, and no file writes."""
    agents = {}
    for path, text in sorted(agent_texts.items()):
        match = re.match(r"---\nname: (.+)\ndescription: (.+)\n---\n\n(.*)", text, re.S)
        agents[match.group(1)] = {
            "description": json.loads(match.group(2)),
            "prompt": match.group(3).strip(),
            "disallowedTools": READ_ONLY_TOOLS_REMOVED,
        }
    return {ROOT / "agents.json": json.dumps(agents, ensure_ascii=False, indent=2) + "\n"}


def zip_folder(folder, target, arcroot):
    with zipfile.ZipFile(target, "w", zipfile.ZIP_DEFLATED) as archive:
        for path in sorted(folder.rglob("*")):
            if any(part in EXCLUDE for part in path.parts) or path.is_dir():
                continue
            info = zipfile.ZipInfo(f"{arcroot}/{path.relative_to(folder).as_posix()}", (2026, 1, 1, 0, 0, 0))
            info.external_attr = (0o755 if path.suffix == ".py" else 0o644) << 16
            info.compress_type = zipfile.ZIP_DEFLATED
            archive.writestr(info, path.read_bytes())


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("--check", action="store_true", help="report stale generated files and write nothing")
    parser.add_argument("--dist", type=Path, help="folder for the release zips")
    args = parser.parse_args(argv)
    agents = agent_files()
    generated = {**agents, **muse_agents(agents)}
    expected_agents = {p.name for p in generated if p.parent.name == "agents"}
    strays = [p for p in (ROOT / "agents").glob("*.md") if p.name not in expected_agents]
    stale = [p for p, text in generated.items() if not p.exists() or p.read_text(encoding="utf-8") != text]
    if args.check:
        for path in stale + strays:
            print(f"stale or stray: {path.relative_to(ROOT)}")
        return 1 if stale or strays else 0
    for path in strays:
        path.unlink()
    for path, text in generated.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    print(f"build: wrote {len(generated)} generated files, removed {len(strays)} strays")
    if args.dist:
        args.dist.mkdir(parents=True, exist_ok=True)
        zip_folder(SKILL, args.dist / "chicken-little-overwatch.zip", "chicken-little-overwatch")
        zip_folder(ROOT, args.dist / "chicken-little-overwatch-plugin.zip", "chicken-little-overwatch-plugin")
        print(f"build: wrote zips to {args.dist}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
